370	static void* outbound_dispatch_task(void* arg)
371	{
372	    (void)arg;
373	    syslog(LOG_INFO, "[%s] Outbound dispatch started\n", TAG);
374	
375	    while (!g_shutdown_requested) {
376	        agent_msg_t msg;
377	        if (message_bus_pop_outbound(&msg, 1000) != OK)
378	            continue;
379	        msg.channel[sizeof(msg.channel) - 1] = '\0';
380	        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';
381	
382	        if (!msg.content) {
383	            syslog(LOG_WARNING, "[%s] Skip outbound message with NULL content\n", TAG);
384	            continue;
385	        }
386	
387	        syslog(LOG_INFO, "[%s] Dispatching response → %s:%s\n", TAG, msg.channel, msg.chat_id);
388	
389	        /* Let registered taps intercept before normal dispatch */
390	        if (mbus_tap_try_deliver(&msg)) {
391	            free(msg.content);
392	            continue;
393	        }
394	
395	        if (strcmp(msg.channel, AGENT_CHAN_FEISHU) == 0) {
396	            bool delivered = false;
397	#ifdef CONFIG_AI_AGENT_FEISHU
398	            const char* app_id = feishu_get_app_id();
399	            if (app_id && app_id[0] != '\0') {
400	                feishu_send_message(msg.chat_id, msg.content);
401	                delivered = true;
402	            }
403	#endif
404	#ifdef CONFIG_AI_AGENT_NODE
405	            if (!delivered) {
406	                delivered = node_client_send_chat_message(
407	                    msg.channel, msg.chat_id, msg.content) == OK;
408	            }
409	#endif
410	            if (!delivered) {
411	                syslog(LOG_WARNING,
412	                    "[%s] Feishu message dropped: no local config "
413	                    "and no gateway\n",
414	                    TAG);
415	            }
416	        } else if (strcmp(msg.channel, AGENT_CHAN_WEBSOCKET) == 0) {
417	            ws_server_send(msg.chat_id, msg.content);
418	#ifdef CONFIG_AI_AGENT_MQTT
419	        } else if (strcmp(msg.channel, AGENT_CHAN_MQTT) == 0) {
420	            mqtt_channel_send(msg.chat_id, msg.content);
421	#endif
422	        } else if (strcmp(msg.channel, AGENT_CHAN_VOICE) == 0) {
423	            /* Check voice cooldown — skip voice dispatch if a recent
424	             * speak call failed, to prevent error-message cascade. */
425	            if (s_voice_cooldown && time(NULL) < s_voice_cooldown_until) {
426	                syslog(LOG_WARNING,
427	                    "[%s] voice cooldown active, dropping message\n", TAG);
428	            } else {
429	                s_voice_cooldown = false;
430	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
431	                /* A spoken reply has to reach the screen as well: until
432	                 * here the voice channel only called voice_channel_speak(),
433	                 * so the answer was audible but never rendered.  On these
434	                 * builds lvgl_ui_channel_send() queues the chat card and
435	                 * then runs the same TTS itself, so it replaces the speak
436	                 * call instead of adding a second one.  When the UI channel
437	                 * is not up (send() fails before speaking) fall back to
438	                 * TTS-only so a headless agent still answers out loud. */
439	                int uret = lvgl_ui_channel_send(msg.content);
440	                if (uret != 0) {
441	                    syslog(LOG_WARNING,
442	                        "[%s] voice reply not rendered (rc=%d), TTS only\n",
443	                        TAG, uret);
444	                    (void)voice_channel_speak(msg.content);
445	                }
446	#else
447	                int vret = voice_channel_speak(msg.content);
448	                if (vret != 0) {
449	                    syslog(LOG_ERR, "[%s] voice_channel_speak failed: %d\n", TAG, vret);
450	                    s_voice_cooldown = true;
451	                    s_voice_cooldown_until = time(NULL) + 5;
452	                }
453	#endif
454	            }
455	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
456	        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) == 0) {
457	            int uret = lvgl_ui_channel_send(msg.content);
458	            if (uret != 0) {
459	                syslog(LOG_ERR, "[%s] lvgl_ui_channel_send failed: %d\n", TAG, uret);
460	            }
461	#endif
462	#ifdef CONFIG_AI_AGENT_NOTIFY_SERVICE
463	        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_NOTIFY) == 0) {
464	            /* Transient toast notice. The toast itself is already popped
465	             * by the notify service (which knows the exact title + color);
466	             * this branch only mirrors to the CLI for debug visibility and
467	             * does NOT enter the chat history. */
468	            pthread_mutex_lock(&g_stdout_lock);
469	            printf("\n[Notify]: %s\nvela> ", msg.content);
470	            fflush(stdout);
471	            pthread_mutex_unlock(&g_stdout_lock);
472	#endif
473	#ifdef CONFIG_AI_AGENT_WEIXIN
474	        } else if (strcmp(msg.channel, AGENT_CHAN_WEIXIN) == 0) {
475	            /* chat_id format: "from_user_id|context_token" */
476	            char uid[64] = "";
477	            const char* ctx = "";
478	            char* sep = strchr(msg.chat_id, '|');
479	            if (sep) {
480	                size_t ulen = (size_t)(sep - msg.chat_id);
481	                if (ulen >= sizeof(uid))
482	                    ulen = sizeof(uid) - 1;
483	                memcpy(uid, msg.chat_id, ulen);
484	                uid[ulen] = '\0';
485	                ctx = sep + 1;
486	            } else {
487	                strncpy(uid, msg.chat_id, sizeof(uid) - 1);
488	            }
489	            weixin_channel_send(uid, ctx, msg.content);
490	#endif
491	        } else if (strcmp(msg.channel, AGENT_CHAN_SYSTEM) == 0) {
492	            syslog(LOG_INFO, "[%s] System message [%s]: %.128s\n", TAG, msg.chat_id, msg.content);
493	#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
494	        } else if (strcmp(msg.channel, AGENT_CHAN_QUICKAPP) == 0) {
495	            quickapp_mq_dispatch(msg.chat_id, msg.content);
496	#endif
497	        } else if (strcmp(msg.channel, "cli") == 0) {
498	            pthread_mutex_lock(&g_stdout_lock);
499	            printf("\n[Agent]: %s\nvela> ", msg.content);
500	            fflush(stdout);
501	            pthread_mutex_unlock(&g_stdout_lock);
502	            /* One printer only.  This syslog line used to carry the full
503	             * reply a second time, and on a board where syslog shares the
504	             * console the user saw the answer twice.  Log the shape of it
505	             * for the record, not the text.
506	             */
507	
508	            syslog(LOG_INFO, "[agent] reply %u bytes\n",
509	                (unsigned)strlen(msg.content));
510	#if defined(CONFIG_AI_AGENT_LVGL_UI) || defined(CONFIG_AI_AGENT_UI_RPMSG)
511	            /* Mirror CLI replies to the LVGL UI so that `ask` responses
512	             * (which come in on the "cli" channel) also render as chat
513	             * cards on screen, not only as terminal text.  send() shows
514	             * the chat screen on first call, so the UI comes up
515	             * automatically when the first reply arrives. */
516	            lvgl_ui_channel_send(msg.content);
517	#endif
518	        } else {
519	            syslog(LOG_WARNING, "[%s] Unknown channel: %s\n", TAG, msg.channel);
520	        }
521	
522	        free(msg.content);
523	    }
524	
525	    syslog(LOG_INFO, "[%s] Outbound dispatch exiting\n", TAG);
526	    return NULL;
527	}
