533	static inline long boot_ms(struct timespec* t0)
534	{
535	    struct timespec now;
536	    clock_gettime(CLOCK_MONOTONIC, &now);
537	    return (long)((now.tv_sec - t0->tv_sec) * 1000L + (now.tv_nsec - t0->tv_nsec) / 1000000L);
538	}
