17	/* Remote-control link: portable protocol state core.
18	 *
19	 * This layer owns the authority model of a remote agent session and has no
20	 * transport, JSON, or OS dependency. It accepts already-decoded structures
21	 * from the codec layer and decides what the device is allowed to believe.
22	 *
23	 * The remote peer is a PC-side bridge that speaks the frozen DeskMate Link
24	 * contract on behalf of an ACP agent (mimocode / kiro-cli). The bridge, not
25	 * this device, is the final authority on permission decisions: everything
26	 * accepted here is still re-validated remotely.
27	 */
28	
29	#pragma once
30	
31	#include <stdbool.h>
32	#include <stddef.h>
33	#include <stdint.h>
34	
35	#ifdef __cplusplus
36	extern "C" {
37	#endif
38	
39	#define REMOTE_NONCE_MAX 48
40	#define REMOTE_EPOCH_MAX 48
41	#define REMOTE_PROMPT_ID_MAX 40
42	#define REMOTE_TOOL_MAX 24
43	#define REMOTE_HINT_MAX 96
44	#define REMOTE_SUMMARY_MAX 128
45	#define REMOTE_BILLING_UNIT_MAX 16
46	#define REMOTE_REQUEST_ID_MAX 40
47	#define REMOTE_TURN_ID_MAX 40
48	#define REMOTE_PROMPT_TEXT_MAX 2048
49	#define REMOTE_OUTPUT_TEXT_MAX 1600
50	#define REMOTE_TRANSCRIPT_MAX 8192
51	
52	/* A model identifier is "<provider>/<model>", and the model part may itself
53	 * contain slashes ("mify/zhipuai/glm-5.3-flash"). */
54	#define REMOTE_MODEL_MAX 64
55	
56	/* How many models the device remembers so they can be picked by number. The
57	 * list is a convenience for typing at a console, not authority: the bridge
58	 * decides what is selectable and refuses anything else. Costs
59	 * REMOTE_MODEL_OPTIONS_MAX * (REMOTE_MODEL_MAX + 1) bytes of link state. */
60	#define REMOTE_MODEL_OPTIONS_MAX 32
61	
62	/* Authority-snapshot liveness. A session that stops producing snapshots is
63	 * treated as down even while the TCP socket looks healthy. Relaxed from 30 s
64	 * to 10 min: some bridges only snapshot on turn events and never on a timer,
65	 * so a 30 s window drops an idle-but-healthy link straight to Offline. */
66	#define REMOTE_SNAPSHOT_TIMEOUT_MS 600000U
67	
68	/* Frozen link limit, in both directions. A peer cannot force an unbounded
69	 * allocation on the device, and an outbound message that would exceed it is
70	 * refused rather than truncated. Note this is a limit on the encoded form:
71	 * escaping can expand a prompt well beyond its own length. */
72	#define REMOTE_MESSAGE_MAX 4096
73	
74	enum remote_state_e {
75	    REMOTE_STATE_OFFLINE,
76	    REMOTE_STATE_IDLE,
77	    REMOTE_STATE_BUSY,
78	    REMOTE_STATE_ATTENTION,
79	    REMOTE_STATE_RESULT,
