365	/* Voice is a control input to this channel, not a chat message: an
366	 * utterance from a PTT button is an instruction for the remote agent, the
367	 * same thing `rask` sends.  Deliberately remote_ctrl_channel_submit() and
368	 * not decide() -- the voice path never produces a permission decision, it
369	 * produces a prompt that later demands one, so the "a permission decision
370	 * is a human typing ronce/rdeny" rule stays intact and no keyword table or
371	 * intent classifier is needed.
372	 */
373	
374	static void voice_sink_to_remote(const char* text, void* ctx)
375	{
376	    char reply[256];
377	
378	    (void)ctx;
379	
380	    /* Non-blocking for the same reason `rask` is: a turn that stops for a
381	     * remote permission request has to leave the console and the button
382	     * adapter free to answer it.
383	     */
384	
385	    if (remote_ctrl_channel_submit(text, reply, sizeof(reply)) != OK) {
386	        syslog(LOG_ERR, "[%s] voice submit: %s\n", TAG, reply);
387	    }
388	}
