390	int remote_ctrl_channel_start(void)
391	{
392	    int ret;
393	
394	    if (!g_configured) {
395	        return OK;
396	    }
397	
398	    if (g_started) {
399	        return OK;
400	    }
401	
402	    ret = agent_task_create(transport_task, "remote_ctrl",
403	        AGENT_REMOTE_CTRL_STACK, NULL, AGENT_REMOTE_CTRL_PRIO);
404	    if (ret != OK) {
405	        syslog(LOG_ERR, "[%s] failed to create transport thread\n", TAG);
406	        return ERROR;
407	    }
408	
409	    g_started = true;
410	
411	    /* Registering here, not in init(), is what keeps this optional: an
412	     * unconfigured channel never claims the voice text, so a board that
413	     * only wants voice chat keeps the chat-bus default untouched.
414	     */
415	
416	    voice_channel_register_sink(voice_sink_to_remote, NULL);
417	    syslog(LOG_INFO, "[%s] started (voice sink registered)\n", TAG);
418	    return OK;
419	}
