797	int remote_ctrl_channel_submit(const char* text, char* out, size_t out_size)
798	{
799	    if (text == NULL || out == NULL || out_size == 0) {
800	        return ERROR;
801	    }
802	
803	    if (!g_configured) {
804	        snprintf(out, out_size, "Error: remote control is not configured");
805	        return ERROR;
806	    }
807	
808	    /* Deliberately does not touch the blocking-wait state: the session's own
809	     * turn reservation is what keeps two turns from overlapping, and nothing
810	     * would clear a wait that no one is performing. */
811	    if (!remote_session_submit_prompt(&g_session, text)) {
812	        describe_submit_failure(text, out, out_size);
813	        return ERROR;
814	    }
815	    /* The submit succeeded, so the turn that is starting belongs to rask:
816	     * mirror its transcript onto the chat surfaces when it lands. */
817	    g_mirror_turn = true;
818	
819	    snprintf(out, out_size,
820	        "Prompt sent. Use 'rstat' for progress; the reply prints in one piece "
821	        "when the turn ends, and 'rreply' re-reads it.");
822	    return OK;
823	}
