846	        snprintf(out, out_size, "Error: remote control is not configured");
847	        return ERROR;
848	    }
849	
850	    /* Only one caller may own the turn slot at a time. The session would refuse
851	     * a second submit anyway; rejecting here keeps the waiters unambiguous. */
852	    pthread_mutex_lock(&g_turn_lock);
853	    if (g_turn_pending) {
854	        pthread_mutex_unlock(&g_turn_lock);
855	        snprintf(out, out_size, "Error: a remote turn is already in progress");
856	        return ERROR;
857	    }
858	    /* Armed before submitting so a turn that completes immediately cannot be
859	     * missed between the submit and the wait. */
860	    g_turn_pending = true;
861	    g_turn_finished = false;
862	    /* The LLM presents its own answer built from the tool result; a mirrored
863	     * raw transcript on top of that would say everything twice. */
864	    g_mirror_turn = false;
865	    pthread_mutex_unlock(&g_turn_lock);
866	
867	    if (!remote_session_submit_prompt(&g_session, text)) {
868	        pthread_mutex_lock(&g_turn_lock);
