873	        return ERROR;
874	    }
875	
876	    clock_gettime(CLOCK_REALTIME, &deadline);
877	    deadline.tv_sec += (time_t)(timeout_ms / 1000);
878	    deadline.tv_nsec += (long)(timeout_ms % 1000) * 1000000L;
879	    if (deadline.tv_nsec >= 1000000000L) {
880	        deadline.tv_sec += 1;
881	        deadline.tv_nsec -= 1000000000L;
882	    }
883	
884	    pthread_mutex_lock(&g_turn_lock);
885	    while (!g_turn_finished) {
886	        if (pthread_cond_timedwait(&g_turn_cond, &g_turn_lock, &deadline) == ETIMEDOUT) {
887	            break;
888	        }
