31	int tool_remote_agent_prompt_execute(const char* input_json, char* output,
32	    size_t output_size)
33	{
34	    cJSON* root;
35	    const char* text;
36	    int ret;
37	
38	    root = cJSON_Parse(input_json);
39	    if (root == NULL) {
40	        snprintf(output, output_size, "Error: invalid JSON input");
41	        return ERROR;
42	    }
43	
44	    text = cJSON_GetStringValue(cJSON_GetObjectItem(root, "text"));
45	    if (text == NULL || text[0] == '\0') {
46	        snprintf(output, output_size, "Error: 'text' is required");
47	        cJSON_Delete(root);
48	        return ERROR;
49	    }
50	
51	    if (strlen(text) > REMOTE_PROMPT_TEXT_MAX) {
52	        snprintf(output, output_size,
53	            "Error: prompt exceeds %d bytes; send a shorter instruction",
54	            REMOTE_PROMPT_TEXT_MAX);
55	        cJSON_Delete(root);
56	        return ERROR;
57	    }
58	
59	    syslog(LOG_INFO, "[%s] forwarding prompt (%u bytes)\n", TAG,
60	        (unsigned)strlen(text));
61	
62	    /* The timeout is fixed rather than model-supplied: a large value would let
63	     * one tool call stall the whole local agent loop. */
64	    ret = remote_ctrl_channel_prompt(text, AGENT_REMOTE_CTRL_TURN_TIMEOUT_MS,
65	        output, output_size);
66	
67	    cJSON_Delete(root);
68	    return ret;
69	}
