71	int tool_remote_agent_status_execute(const char* input_json, char* output,
72	    size_t output_size)
73	{
74	    struct remote_status_s status;
75	    size_t used;
76	
77	    (void)input_json;
78	
79	    if (remote_ctrl_channel_status(&status) != OK) {
80	        snprintf(output, output_size,
81	            "Remote control is not configured on this device.");
82	        return OK;
83	    }
84	
85	    used = (size_t)snprintf(output, output_size, "Remote agent: %s",
86	        remote_state_name(status.state));
87	    if (used >= output_size) {
88	        return OK;
89	    }
90	
91	    if (status.summary[0] != '\0') {
92	        used += (size_t)snprintf(output + used, output_size - used, " (%s)",
93	            status.summary);
94	        if (used >= output_size) {
95	            return OK;
96	        }
97	    }
98	
99	    if (status.billing[0] != '\0') {
100	        used += (size_t)snprintf(output + used, output_size - used, "\n%s",
101	            status.billing);
102	        if (used >= output_size) {
103	            return OK;
104	        }
105	    }
106	
107	    /* Say plainly that this needs a person: the model has no tool for it and
108	     * should report back rather than keep retrying the prompt. */
109	    if (status.has_prompt) {
110	        used += (size_t)snprintf(output + used, output_size - used,
111	            "\nWaiting for a human to approve or deny '%s' on this device"
112	            "%s. You cannot answer this yourself; tell the user it is pending.",
113	            status.prompt.tool,
114	            status.decision_in_flight ? " (a decision was already sent)" : "");
115	        if (used >= output_size) {
116	            return OK;
117	        }
118	    }
119	
120	    if (status.turn_active) {
121	        used += (size_t)snprintf(output + used, output_size - used,
122	            "\nA remote turn is currently running.");
123	        if (used >= output_size) {
124	            return OK;
125	        }
126	    }
127	
128	    if (!status.chat_supported && status.state != REMOTE_STATE_OFFLINE) {
129	        snprintf(output + used, output_size - used,
130	            "\nThe remote bridge does not offer chat turns, so prompts cannot "
131	            "be sent.");
132	    }
133	
134	    return OK;
135	}
