17	/*
18	 * ptt_button.c — AP-side physical Push-to-Talk button (路 B M5).
19	 *
20	 * BK7258 dual-core: the physical user buttons (S1/S2/S3 = GPIO13/12/8) and
21	 * the voice pipeline (voice_channel_*) both live on the AP core, as does the
22	 * ui_rpmsg_client shim that drives the CP UI.  So PTT is entirely an AP
23	 * affair — no reverse CP→AP RPMsg is needed:
24	 *
25	 *   S1 press   → voice_channel_start()          + set_ptt(RECORDING)  → CP
26	 *   S1 release → set_ptt(PROCESSING) → CP
27	 *               voice_channel_stop_with_text()   (blocks ~ASR finalize)
28	 *               send_user(asr_text)  → CP (right bubble echo)
29	 *               voice_channel_dispatch(asr_text) → agent → LLM → reply
30	 *               set_ptt(IDLE)         → CP
31	 *
32	 * Hold-to-talk semantics (press=record, release=ASR), as specified in
33	 * UI方案.md §2.5 ("PTT=按下录音→松手触发 ASR；可挂 S1").  Button index,
34	 * long-press threshold, and devpath are Kconfig-tunable.
35	 *
36	 * The blocking voice_channel_stop_with_text() runs in this dedicated thread
37	 * (not the LVGL/agent thread), so the ASR finalize (~300-800ms TLS + stream)
38	 * never stalls rendering or the agent loop.  A local busy flag serializes
39	 * sessions: a second press during processing is ignored, mirroring the
40	 * on-screen ptt_btn_event_cb's is_processing guard.
41	 *
42	 * Only compiled under CONFIG_AI_AGENT_PTT, which depends on a UI channel
43	 * (LVGL_UI or UI_RPMSG) so the lvgl_ui_channel_* symbols resolve.
44	 */
