105	static void ptt_on_press(void)
106	{
107	  int ret;
108	
109	  pthread_mutex_lock(&g_ptt_lock);
110	  if (g_ptt_busy || g_ptt_recording)
111	    {
112	      pthread_mutex_unlock(&g_ptt_lock);
113	      return;  /* ignore re-press during an active session */
114	    }
115	  g_ptt_recording = true;
116	  pthread_mutex_unlock(&g_ptt_lock);
117	
118	  ret = voice_channel_start();
119	  if (ret != 0)
120	    {
121	      syslog(LOG_ERR, "[%s] voice_channel_start failed rc=%d\n", TAG, ret);
122	      pthread_mutex_lock(&g_ptt_lock);
123	      g_ptt_recording = false;
124	      pthread_mutex_unlock(&g_ptt_lock);
125	      return;
126	    }
127	
128	#if PTT_HAVE_UI
129	  (void)lvgl_ui_channel_set_ptt(LVGL_UI_PTT_RECORDING);
130	#endif
131	  syslog(LOG_INFO, "[%s] PTT press → recording\n", TAG);
132	}
