134	static void ptt_on_release(void)
135	{
136	  char asr_text[CONFIG_AI_AGENT_PTT_ASR_CAP];
137	  int ret;
138	  bool asr_failed = false;
139	
140	  pthread_mutex_lock(&g_ptt_lock);
141	  if (!g_ptt_recording)
142	    {
143	      /* release without a matched press (e.g. baseline edge) — ignore */
144	      pthread_mutex_unlock(&g_ptt_lock);
145	      return;
146	    }
147	  g_ptt_recording = false;
148	  g_ptt_busy = true;
149	  pthread_mutex_unlock(&g_ptt_lock);
150	
151	#if PTT_HAVE_UI
152	  (void)lvgl_ui_channel_set_ptt(LVGL_UI_PTT_PROCESSING);
153	#endif
154	  syslog(LOG_INFO, "[%s] PTT release → ASR\n", TAG);
155	
156	  /* Blocks until ASR finalizes the stream.  Fine here — dedicated thread. */
157	  asr_text[0] = '\0';
158	  ret = voice_channel_stop_with_text(asr_text, sizeof(asr_text));
159	  if (ret != 0)
160	    {
161	      syslog(LOG_ERR, "[%s] voice_channel_stop_with_text failed rc=%d\n",
162	             TAG, ret);
163	      asr_failed = true;
164	#if PTT_HAVE_UI
165	      /* ASR cannot run without the network (or its credentials).  Show a
166	       * red-bar card that says so; otherwise the screen simply drops back
167	       * to the pet with no clue about what went wrong. */
168	      (void)lvgl_ui_channel_send_ex(
169	          "语音识别不可用：请检查网络和语音识别配置。", 0xff5252);
170	#endif
171	      goto done;
172	    }
173	
174	  if (asr_text[0] == '\0')
175	    {
176	      syslog(LOG_WARNING, "[%s] no speech recognized\n", TAG);
177	#if PTT_HAVE_UI
178	      /* The stream finalized cleanly but produced no text.  That is a *user*
179	       * miss (didn't speak / too far from the mic), not a broken link, so it
180	       * must look different from the red "ASR unavailable" card above.  An
181	       * amber hint tells them to try again rather than silently dropping back
182	       * to the idle pet, which was indistinguishable from success. */
183	      (void)lvgl_ui_channel_send_ex(
184	          "没听到语音，请靠近麦克风再说一次。", 0xffa31f);
185	#endif
186	      goto done;
187	    }
188	
189	  syslog(LOG_INFO, "[%s] recognized: %s\n", TAG, asr_text);
190	
191	#if PTT_HAVE_UI
192	  /* Echo the user utterance as a right-aligned bubble on CP. */
193	  (void)lvgl_ui_channel_send_user(asr_text);
194	#endif
195	
196	  /* Route to the agent (message_bus → LLM → reply bubble + TTS).
197	   * voice_channel_dispatch is the single sink point; on AP it is real. */
198	  voice_channel_dispatch(asr_text);
199	
200	done:
201	  pthread_mutex_lock(&g_ptt_lock);
202	  g_ptt_busy = false;
203	  pthread_mutex_unlock(&g_ptt_lock);
204	
205	#if PTT_HAVE_UI
206	  (void)lvgl_ui_channel_set_ptt(LVGL_UI_PTT_IDLE);
207	  /* On ASR failure, drive the pet to ERROR (5) AFTER the PTT-IDLE mirror so
208	   * the RPMsg FIFO delivers ERROR last — the pet shows red+shake instead of
209	   * silently going idle-green.  pet_status_view.h: 5=PET_STATE_ERROR. */
210	  if (asr_failed)
211	    (void)lvgl_ui_channel_set_pet_error("语音识别不可用\n请检查网络和凭据");
212	#endif
213	}
