215	static void* ptt_button_thread(void* arg)
216	{
217	  const char* devpath = CONFIG_AI_AGENT_PTT_DEVPATH;
218	  struct btn_pollevents_s pe;
219	  struct pollfd pfd;
220	  btn_buttonset_t supported;
221	  btn_buttonset_t last;
222	  bool have_baseline = false;
223	  int fd;
224	  int bit = ptt_button_bit();
225	
226	  (void)arg;
227	
228	  fd = open(devpath, O_RDONLY);
229	  if (fd < 0)
230	    {
231	      syslog(LOG_ERR, "[%s] open %s failed: %d\n", TAG, devpath, errno);
232	      return NULL;
233	    }
234	
235	  supported = 0;
236	  if (ioctl(fd, BTNIOC_SUPPORTED, (unsigned long)&supported) < 0)
237	    {
238	      syslog(LOG_ERR, "[%s] BTNIOC_SUPPORTED failed: %d\n", TAG, errno);
239	      close(fd);
240	      return NULL;
241	    }
242	
243	  if ((supported & (btn_buttonset_t)bit) == 0)
244	    {
245	      syslog(LOG_ERR, "[%s] button idx %d not in supported set 0x%08lx\n",
246	             TAG, CONFIG_AI_AGENT_PTT_BUTTON_IDX, (unsigned long)supported);
247	      close(fd);
248	      return NULL;
249	    }
250	
251	  /* Wake on both edges of our PTT button only. */
252	  pe.bp_press   = (btn_buttonset_t)bit;
253	  pe.bp_release = (btn_buttonset_t)bit;
254	  (void)ioctl(fd, BTNIOC_POLLEVENTS, (unsigned long)&pe);
255	
256	  pfd.fd     = fd;
257	  pfd.events = POLLIN;
258	  last       = 0;
259	
260	  syslog(LOG_INFO, "[%s] watching %s button %d (hold-to-talk)\n", TAG,
261	         devpath, CONFIG_AI_AGENT_PTT_BUTTON_IDX);
262	
263	  for (;;)
264	    {
265	      btn_buttonset_t cur;
266	      btn_buttonset_t change;
267	      ssize_t nread;
268	
269	      if (poll(&pfd, 1, -1) < 0)
270	        {
271	          if (errno == EINTR)
272	            {
273	              continue;
274	            }
275	          syslog(LOG_ERR, "[%s] poll failed: %d\n", TAG, errno);
276	          break;
277	        }
278	
279	      if ((pfd.revents & POLLIN) == 0)
280	        {
281	          continue;
282	        }
283	
284	      nread = read(fd, &cur, sizeof(cur));
285	      if (nread != (ssize_t)sizeof(cur))
286	        {
287	          continue;
288	        }
289	
290	      if (!have_baseline)
291	        {
292	          last = cur;
293	          have_baseline = true;
294	          continue;
295	        }
296	
297	      change = cur ^ last;
298	      if ((change & (btn_buttonset_t)bit) == 0)
299	        {
300	          last = cur;
301	          continue;  /* our button didn't change */
302	        }
303	
304	      if (cur & (btn_buttonset_t)bit)
305	        {
306	          ptt_on_press();
307	        }
308	      else
309	        {
310	          ptt_on_release();
311	        }
312	      last = cur;
313	    }
314	
315	  close(fd);
316	  return NULL;
317	}
