162	/**
163	 * Runs in a background thread: waits for network, then starts all
164	 * network-dependent services. Main thread is NOT blocked.
165	 */
166	static void* network_watch_task(void* arg)
167	{
168	    (void)arg;
169	    syslog(LOG_INFO, "[%s] Network watcher started\n", TAG);
170	
171	    network_wifi_reconnect();
172	
173	    if (network_wait_connected(30000) == OK) {
174	        syslog(LOG_INFO, "[%s] Network connected: %s\n", TAG, network_get_ip());
175	
176	#if AGENT_SKILL_SYNC_ENABLED
177	        /* Sync skills from Bitable before starting agent loop */
178	        if (skill_sync_from_bitable() != OK) {
179	            syslog(LOG_WARNING, "[%s] Bitable skill sync failed, using local skills\n", TAG);
180	        }
181	#endif
182	
183	#ifdef CONFIG_AI_AGENT_FEISHU
184	        if (feishu_bot_start() != OK)
185	            syslog(LOG_WARNING, "[%s] feishu_bot_start failed\n", TAG);
186	#endif
187	        if (agent_loop_start() != OK)
188	            syslog(LOG_WARNING, "[%s] agent_loop_start failed\n", TAG);
189	#ifdef CONFIG_AI_AGENT_WS_SERVER
190	        if (ws_server_start() != OK)
191	            syslog(LOG_WARNING, "[%s] ws_server_start failed\n", TAG);
192	#endif
193	#ifdef CONFIG_AI_AGENT_NODE
194	        if (node_client_start() != OK)
195	            syslog(LOG_WARNING, "[%s] node_client_start failed\n", TAG);
196	#endif
197	#ifdef CONFIG_AI_AGENT_MQTT
198	        if (mqtt_channel_start() != OK)
199	            syslog(LOG_WARNING, "[%s] mqtt_channel_start failed\n", TAG);
200	#endif
201	#ifdef CONFIG_AI_AGENT_REMOTE_CTRL
202	        if (remote_ctrl_channel_start() != OK)
203	            syslog(LOG_WARNING, "[%s] remote_ctrl_channel_start failed\n", TAG);
204	#endif
205	#ifdef CONFIG_AI_AGENT_WEIXIN
206	        if (weixin_channel_start() != OK)
207	            syslog(LOG_WARNING, "[%s] weixin_channel_start failed\n", TAG);
208	#endif
209	
210	        /* MCP servers were restored from config_store during mcp_client_init
211	         * (before the link was up), so the initial discover likely failed.
212	         * Retry now that the network is up so tools are registered before
213	         * the notify poller first runs. */
214	#ifdef CONFIG_AI_AGENT_MCP
215	        mcp_client_discover();
216	#endif
217	#ifdef CONFIG_AI_AGENT_NOTIFY_SERVICE
218	        if (notify_service_start() != OK)
219	            syslog(LOG_WARNING, "[%s] notify_service_start failed\n", TAG);
220	#endif
221	
222	        syslog(LOG_INFO, "[%s] All network services started!\n", TAG);
223	
224	#ifdef CONFIG_AI_AGENT_NET_RPMSG
225	        g_net_services_started = true;
226	#endif
227	    } else {
228	        syslog(LOG_WARNING, "[%s] Network timeout — net services not started.\n", TAG);
229	        syslog(LOG_WARNING, "[%s] Use 'config_show' / 'set_*' CLI commands to configure.\n", TAG);
230	    }
231	
232	#ifdef CONFIG_AI_AGENT_NET_RPMSG
233	    /* Register listener for network state changes — auto-restart services on reconnect */
234	    network_register_listener(net_state_change_cb, NULL);
235	
236	    /* Keep thread alive to handle reconnection events */
237	    while (!g_shutdown_requested) {
238	        sleep(1);
239	    }
240	#endif
241	
242	    return NULL;
243	}
