272	static void parse_broker(const char* broker)
273	{
274	    const char* colon = strrchr(broker, ':');
275	    size_t host_length;
276	
277	    if (colon != NULL && colon != broker) {
278	        host_length = (size_t)(colon - broker);
279	        if (host_length > REMOTE_MQTT_HOST_MAX) {
280	            host_length = REMOTE_MQTT_HOST_MAX;
281	        }
282	        memcpy(g_broker_host, broker, host_length);
283	        g_broker_host[host_length] = '\0';
284	        snprintf(g_broker_port, sizeof(g_broker_port), "%.*s",
285	            (int)sizeof(g_broker_port) - 1, colon + 1);
286	    } else {
287	        snprintf(g_broker_host, sizeof(g_broker_host), "%s", broker);
288	        snprintf(g_broker_port, sizeof(g_broker_port), "%d",
289	            AGENT_MQTT_DEFAULT_PORT);
290	    }
291	}
