98	static int open_media_lane(void** out_player, const char* stream,
99	    unsigned int sample_rate, unsigned int channels,
100	    unsigned int bits_per_sample)
101	{
102	    void* player = media_player_open(stream);
103	    if (!player) {
104	        syslog(LOG_ERR, "[%s] media_player_open(%s) failed\n", TAG, stream);
105	        return -EIO;
106	    }
107	
108	    char opts[PB_OPTIONS_LEN];
109	    snprintf(opts, sizeof(opts),
110	        "format=s%ule:sample_rate=%u:ch_layout=%s",
111	        bits_per_sample, sample_rate,
112	        (channels == 1) ? "mono" : "stereo");
113	
114	    int ret = media_player_prepare(player, NULL, opts);
115	    if (ret < 0) {
116	        syslog(LOG_ERR, "[%s] prepare(%s) failed: %d\n", TAG, stream, ret);
117	        media_player_close(player, 0);
118	        return ret;
119	    }
120	
121	    ret = media_player_start(player);
122	    if (ret < 0) {
123	        syslog(LOG_ERR, "[%s] start(%s) failed: %d\n", TAG, stream, ret);
124	        media_player_close(player, 0);
