132	static int open_media_player(audio_playback_t* pb,
133	    unsigned int sample_rate, unsigned int channels,
134	    unsigned int bits_per_sample)
135	{
136	    if (s_active_player) {
137	        syslog(LOG_WARNING, "[%s] force closing stale player\n", TAG);
138	        media_player_stop(s_active_player);
139	        media_player_close(s_active_player, 0);
140	        s_active_player = NULL;
141	        usleep(100000);
142	    }
143	
144	    /* Prefer the dedicated TTS lane (its own abufsrc in graph.conf, so a
145	     * music player or recorder session can hold the Music lane without
146	     * either side force-closing the other), then the generic Music lane
147	     * for graphs that never defined a TTS entry. */
148	    void* player = NULL;
149	    int ret = open_media_lane(&player, MEDIA_STREAM_TTS,
150	        sample_rate, channels, bits_per_sample);
151	    if (ret < 0) {
152	        syslog(LOG_WARNING, "[%s] TTS lane unavailable (%d), trying Music\n",
153	            TAG, ret);
154	        ret = open_media_lane(&player, MEDIA_STREAM_MUSIC,
155	            sample_rate, channels, bits_per_sample);
156	        if (ret < 0) {
157	            return ret;
158	        }
159	    }
160	
161	    pb->player = player;
162	    pb->bytes_per_frame = (int)((bits_per_sample / 8) * channels);
163	    s_active_player = player;
164	
165	    syslog(LOG_INFO, "[%s] opened (%uHz %uch %ubit) via media_player\n",
166	        TAG, sample_rate, channels, bits_per_sample);
167	    return 0;
168	}
