174	static int open_nuttx_playback(audio_playback_t* pb, const char* dev_path,
175	    unsigned int sample_rate, unsigned int channels,
176	    unsigned int bits_per_sample)
177	{
178	    struct audio_caps_desc_s caps;
179	    struct ap_buffer_info_s info;
180	    struct audio_buf_desc_s buf_desc;
181	    struct mq_attr attr;
182	    int fd;
183	    int ret;
184	    unsigned int i;
185	
186	    /* The BK7258 pcm0p lower-half plays 16-bit mono S16_LE. */
187	    if (channels != 1 || bits_per_sample != 16) {
188	        syslog(LOG_WARNING,
189	            "[%s] NuttX audio playback requires 16-bit mono\n", TAG);
190	        return -ENOTSUP;
191	    }
192	
193	    fd = open(dev_path, O_WRONLY);
194	    if (fd < 0) {
195	        syslog(LOG_ERR, "[%s] open(%s) failed, errno=%d\n",
196	            TAG, dev_path, errno);
197	        return -errno;
198	    }
199

199	
200	    ret = ioctl(fd, AUDIOIOC_RESERVE, 0);
201	    if (ret < 0) {
202	        syslog(LOG_ERR, "[%s] AUDIOIOC_RESERVE failed: %d\n", TAG, ret);
203	        close(fd);
204	        return ret;
205	    }
206	
207	    memset(&caps, 0, sizeof(caps));
208	    caps.caps.ac_len            = sizeof(caps.caps);
209	    caps.caps.ac_type           = AUDIO_TYPE_OUTPUT;
210	    caps.caps.ac_subtype        = AUDIO_FMT_PCM;
211	    caps.caps.ac_channels       = (uint8_t)channels;
212	    caps.caps.ac_controls.hw[0] = (uint16_t)(sample_rate & 0xFFFFu);
213	    caps.caps.ac_controls.b[3]  = (uint8_t)(sample_rate >> 16);
214	    caps.caps.ac_controls.b[2]  = (uint8_t)bits_per_sample;
215	
216	    ret = ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&caps);
217	    if (ret < 0) {
218	        syslog(LOG_ERR, "[%s] AUDIOIOC_CONFIGURE failed: %d\n", TAG, ret);
219	        close(fd);
220	        return ret;
221	    }
222	
223	    /* Message queue: the driver posts AUDIO_MSG_DEQUEUE when a buffer has
224	     * been drained by the DMA so we can reuse it. */
225	    snprintf(pb->mq_name, sizeof(pb->mq_name),
226	        "/audio_pb_mq_%d", (int)getpid());
227	
228	    attr.mq_maxmsg  = 16;
229	    attr.mq_msgsize = sizeof(struct audio_msg_s);
230	    attr.mq_flags   = 0;
231	    attr.mq_curmsgs = 0;
232	
233	    mq_unlink(pb->mq_name);
234	    pb->mq = mq_open(pb->mq_name, O_RDWR | O_CREAT, 0644, &attr);
235	    if (pb->mq == (mqd_t)-1) {
236	        syslog(LOG_ERR, "[%s] mq_open failed: %d\n", TAG, errno);
237	        close(fd);
238	        return -errno;
239	    }
240	
241	    ret = ioctl(fd, AUDIOIOC_REGISTERMQ, (unsigned long)pb->mq);
242	    if (ret < 0) {
243	        syslog(LOG_ERR, "[%s] AUDIOIOC_REGISTERMQ failed: %d\n", TAG, ret);
244	        mq_close(pb->mq);
245	        mq_unlink(pb->mq_name);
246	        close(fd);
247	        return ret;
248	    }
249	
250	    ret = ioctl(fd, AUDIOIOC_GETBUFFERINFO, (unsigned long)&info);
251	    if (ret < 0) {
252	        info.nbuffers    = 4;
253	        info.buffer_size = 4096;
254	    }
255	
256	    if (info.nbuffers > PB_MAX_BUFS) {
257	        info.nbuffers = PB_MAX_BUFS;
258	    }
259	    if (info.nbuffers == 0) {
260	        info.nbuffers = 4;
261	    }
262	    if (info.buffer_size == 0) {
263	        info.buffer_size = 4096;
264	    }
265	
266	    for (i = 0; i < (unsigned int)info.nbuffers; i++) {
267	        struct ap_buffer_s* apb = NULL;
268	
269	        memset(&buf_desc, 0, sizeof(buf_desc));
270	        buf_desc.numbytes  = info.buffer_size;
271	        buf_desc.u.pbuffer = &apb;
272	        ret = ioctl(fd, AUDIOIOC_ALLOCBUFFER, (unsigned long)&buf_desc);
273	        if (ret < 0 || apb == NULL) {
274	            syslog(LOG_ERR, "[%s] AUDIOIOC_ALLOCBUFFER failed: %d\n",
275	                TAG, ret);
276	            while (i > 0) {
277	                i--;
278	                memset(&buf_desc, 0, sizeof(buf_desc));
279	                buf_desc.u.buffer = pb->apbs[i];
280	                ioctl(fd, AUDIOIOC_FREEBUFFER, (unsigned long)&buf_desc);
281	            }
282	            ioctl(fd, AUDIOIOC_UNREGISTERMQ, (unsigned long)pb->mq);
283	            mq_close(pb->mq);
284	            mq_unlink(pb->mq_name);
285	            close(fd);
286	            return (ret < 0) ? ret : -ENOMEM;
287	        }
288	        pb->apbs[i]  = apb;
289	        pb->freeq[i] = apb;
290	    }
291	
292	    pb->fd             = fd;
293	    pb->nbuffers       = (unsigned int)info.nbuffers;
294	    pb->free_count     = pb->nbuffers;
295	    pb->buf_bytes      = (unsigned int)info.buffer_size;
296	    pb->started        = 0;
297	    pb->bytes_per_frame = (int)((bits_per_sample / 8) * channels);
298	
299	    syslog(LOG_INFO,
300	        "[%s] opened NuttX playback (%s, %uHz, %uch, %ubit, %u x %uB)\n",
301	        TAG, dev_path, sample_rate, channels, bits_per_sample,
302	        pb->nbuffers, pb->buf_bytes);
303	    return 0;
304	}
