306	/* Receive one message, folding any DEQUEUE'd buffer back into the free list.
307	 * Returns 0 (processed), -ETIMEDOUT, or -EIO. */
308	static int nuttx_recv_one(audio_playback_t* pb, int timeout_ms)
309	{
310	    struct audio_msg_s msg;
311	    struct timespec to;
312	    unsigned int prio;
313	    ssize_t n;
314	
315	    clock_gettime(CLOCK_REALTIME, &to);
316	    to.tv_sec  += (time_t)(timeout_ms / 1000);
317	    to.tv_nsec += (long)(timeout_ms % 1000) * 1000000L;
318	    if (to.tv_nsec >= 1000000000L) {
319	        to.tv_sec++;
320	        to.tv_nsec -= 1000000000L;
321	    }
322	
323	    n = mq_timedreceive(pb->mq, (char*)&msg, sizeof(msg), &prio, &to);
324	    if (n < 0) {
325	        return (errno == ETIMEDOUT) ? -ETIMEDOUT : -errno;
326	    }
327	
328	    if (msg.msg_id == AUDIO_MSG_DEQUEUE && msg.u.ptr) {
329	        if (pb->free_count < pb->nbuffers) {
330	            pb->freeq[pb->free_count++] = (struct ap_buffer_s*)msg.u.ptr;
331	        }
332	        return 0;
333	    }
334	
335	    if (msg.msg_id == AUDIO_MSG_IOERR) {
336	        return -EIO;
337	    }
338	
339	    /* COMPLETE / UNDERRUN / others: not a buffer, keep polling. */
340	    return 0;
341	}
342	
343	static struct ap_buffer_s* nuttx_get_free_buffer(audio_playback_t* pb)
344	{
345	    for (;;) {
346	        if (pb->stopped) {
347	            return NULL;
348	        }
349	        if (pb->free_count > 0) {
350	            return pb->freeq[--pb->free_count];
351	        }
352	
353	        int r = nuttx_recv_one(pb, 500);
354	        if (r == -EIO) {
355	            return NULL;
356	        }
357	        /* -ETIMEDOUT or 0: loop and re-check stopped / free_count. */
358	    }
359	}
360	
361	static int nuttx_write(audio_playback_t* pb, const void* buf, size_t len)
362	{
363	    const uint8_t* src = (const uint8_t*)buf;
364	    size_t remaining = len;
365	
366	    while (remaining > 0) {
367	        struct ap_buffer_s* apb = nuttx_get_free_buffer(pb);
368	        if (!apb) {
369	            return pb->stopped ? -ECANCELED : -EIO;
370	        }
371	
372	        size_t chunk = remaining;
373	        if (chunk > pb->buf_bytes) {
374	            chunk = pb->buf_bytes;
375	        }
376	
377	        memcpy(apb->samp, src, chunk);
378	        apb->nbytes  = (apb_samp_t)chunk;
379	        apb->curbyte = 0;
380	
381	        struct audio_buf_desc_s desc;
382	        memset(&desc, 0, sizeof(desc));
383	        desc.numbytes = chunk;
384	        desc.u.buffer = apb;
385	
386	        int ret = ioctl(pb->fd, AUDIOIOC_ENQUEUEBUFFER, (unsigned long)&desc);
387	        if (ret < 0) {
388	            syslog(LOG_ERR, "[%s] AUDIOIOC_ENQUEUEBUFFER failed: %d\n",
389	                TAG, ret);
390	            return ret;
391	        }
392	
393	        if (!pb->started) {
394	            ret = ioctl(pb->fd, AUDIOIOC_START, 0);
395	            if (ret < 0) {
396	                syslog(LOG_ERR, "[%s] AUDIOIOC_START failed: %d\n", TAG, ret);
397	                return ret;
398	            }
399	            pb->started = 1;
400	        }
401	
402	        src += chunk;
403	        remaining -= chunk;
404	        pb->total_written += chunk;
405	    }
406	
407	    return (int)len;
408	}

1198	int voice_channel_speak(const char* text)
1199	{
1200	    if (!text || text[0] == '\0') {
1201	        return -EINVAL;
1202	    }
1203	
1204	    /* ── Serialize concurrent speak calls ── */
1205	    /* If another thread is already speaking, abort its TTS playback
1206	     * so we don't overlap media_player sessions (which causes the
1207	     * media framework to attempt a ~1.3GB allocation and crash). */
1208	    pthread_mutex_lock(&s_voice.lock);
1209	    if (s_voice.tts_pb) {
1210	        syslog(LOG_INFO, "[%s] speak: aborting previous TTS\n", TAG);
1211	        s_voice.tts_abort = 1;
1212	        audio_playback_stop(s_voice.tts_pb);
1213	    }
1214	    pthread_mutex_unlock(&s_voice.lock);
1215	
1216	    pthread_mutex_lock(&s_voice.speak_lock);
1217	
1218	    /* ── AEC workaround: reject TTS while PTT is recording ── */
1219	    pthread_mutex_lock(&s_voice.lock);
1220	    if (s_voice.state != VOICE_IDLE) {
1221	        pthread_mutex_unlock(&s_voice.lock);
1222	        pthread_mutex_unlock(&s_voice.speak_lock);
1223	        syslog(LOG_INFO,
1224	            "[%s] speak: skipped, recording active\n", TAG);
1225	        return -EBUSY;
1226	    }
1227	    pthread_mutex_unlock(&s_voice.lock);
1228	
1229	    /* Without credentials the network synth can only fail.  Bail out before
1230	     * touching the audio hardware (beep + playback open/close): that path
1231	     * stalls the caller for seconds and churns the audio driver for nothing. */
1232	    if (!voice_tts_is_ready()) {
1233	        syslog(LOG_WARNING,
1234	            "[%s] speak: TTS not configured, skipped\n", TAG);
1235	        pthread_mutex_unlock(&s_voice.speak_lock);
1236	        return -ENOENT;
1237	    }
1238	
1239	    /* Work on a mutable copy so we can strip markdown in-place */
1240	    size_t text_len = strlen(text);
1241	    char* clean = malloc(text_len + 1);
1242	
1243	    if (!clean) {
1244	        pthread_mutex_unlock(&s_voice.speak_lock);
1245	        return -ENOMEM;
1246	    }
1247	
1248	    memcpy(clean, text, text_len + 1);
1249	    tts_strip_markdown(clean);
1250	
1251	    /* If stripping left nothing, bail out */
1252	    if (clean[0] == '\0') {
1253	        free(clean);
1254	        pthread_mutex_unlock(&s_voice.speak_lock);
1255	        return 0;
1256	    }
1257	
1258	    syslog(LOG_INFO, "[%s] speak: \"%.*s\" (%zu bytes)\n",
1259	        TAG, 60, clean, strlen(clean));
1260	
1261	    clock_gettime(CLOCK_MONOTONIC, &s_tts_start);
1262	    s_tts_first_chunk = 0;
1263	
1264	    if (s_asr_done_ts.tv_sec > 0) {
1265	        long llm_ms = (s_tts_start.tv_sec - s_asr_done_ts.tv_sec) * 1000
1266	            + (s_tts_start.tv_nsec - s_asr_done_ts.tv_nsec) / 1000000;
1267	        syslog(LOG_INFO, "[%s] LLM latency: %ldms\n", TAG, llm_ms);
1268	    }
1269	
1270	    /* Play a short attention beep before the (slower) network synthesis so
1271	     * a notification is audible immediately. Non-fatal on failure. */
1272	    voice_channel_beep(1000, 200);
1273	
1274	    /* Try streaming TTS first (callback per chunk).
1275	     * NOTE: playback must match the REST v3 synth sample rate
1276	     * (AGENT_VOICE_SAMPLE_RATE = 16kHz), not the old WS v1 24kHz. */
1277	    audio_playback_t* pb = audio_playback_open(
1278	        AGENT_AUDIO_PLAYBACK_DEV,
1279	        AGENT_VOICE_SAMPLE_RATE,
1280	        AGENT_VOICE_CHANNELS,
1281	        AGENT_VOICE_BITS);
1282	
1283	    if (!pb) {
1284	        syslog(LOG_ERR, "[%s] playback open failed\n", TAG);
1285	        free(clean);
1286	        pthread_mutex_unlock(&s_voice.speak_lock);
1287	        return -EIO;
1288	    }
1289	
1290	    /* Register active playback so voice_channel_start() can abort it */
1291	    pthread_mutex_lock(&s_voice.lock);
1292	    s_voice.tts_abort = 0;
1293	    s_voice.tts_pb = pb;
1294	    pthread_mutex_unlock(&s_voice.lock);
1295	
1296	    /* Synthesize the reply sentence-by-sentence: a long text sent as one
1297	     * request both truncates at the streaming buffer cap and reads as one
1298	     * monotonous run.  Each segment is its own synth request written, in
1299	     * order, to the one open playback handle — sentence terminators stay with
1300	     * their segment, giving the engine a natural pause at each boundary. */
1301	    int ret = 0;
1302	    char* seg = clean;
1303	
1304	    while (*seg && ret == 0 && !s_voice.tts_abort) {
1305	        char* next = tts_next_segment(seg);
1306	        char saved = *next;
1307	
1308	        if (next == seg) {
1309	            break;  /* defensive: no forward progress */
1310	        }
