5	export function mimoAcpPort(value) {
6	  const port = typeof value === "number" ? value : Number(value);
7	  if (!Number.isInteger(port) || port < 1 || port > 65_535) {
8	    throw new TypeError("MiMo ACP port must be an integer from 1 through 65535");
