17	function validateReady(path, sessionId, url) {
18	  if (typeof path !== "string" || !isAbsolute(path)) {
19	    throw new TypeError("MiMo attach ready file must be an absolute path");
20	  }
21	  if (typeof sessionId !== "string" || !/^[A-Za-z0-9_-]{1,128}$/.test(sessionId)) {
22	    throw new TypeError("MiMo ACP session id is invalid");
23	  }
24	  if (typeof url !== "string" || !/^http:\/\/127\.0\.0\.1:[1-9][0-9]{0,4}$/.test(url)) {
25	    throw new TypeError("MiMo attach URL must use 127.0.0.1 and an explicit port");
26	  }
27	}
