29	export async function publishMimoAttachReady(path, { sessionId, url }) {
30	  validateReady(path, sessionId, url);
31	  await mkdir(dirname(path), { recursive: true, mode: 0o700 });
32	  const temporary = `${path}.${process.pid}.${randomBytes(8).toString("hex")}.tmp`;
33	  const document = `${JSON.stringify({ v: 1, url, session_id: sessionId })}\n`;
34	  try {
35	    await writeFile(temporary, document, { encoding: "utf8", mode: 0o600, flag: "wx" });
36	    await rename(temporary, path);
37	  } catch (error) {
38	    await rm(temporary, { force: true }).catch(() => {});
39	    throw error;
40	  }
41	}
