 *   bot_m   0 — chat_list bottom flush with the round-face bottom edge
 *               (y=260) */
int32_t side_m   = (round_d * 6)  / 100;   /* chat_list side gutter */
int32_t top_m    = (round_d * 14) / 100;   /* chat_list top gutter */
