2289	/* Hold time scales with how much there is to read: a fixed window makes a
2290	 * one-line Gerrit change linger long past the point of usefulness while a long
2291	 * Jira summary gets yanked away mid-sentence.  ~60ms per UTF-8 byte ≈ 180ms per
2292	 * CJK char (a slow skim), floored at LVGL_UI_NOTICE_MS and capped at 30s. */
2293	static uint32_t notice_duration_ms(const char* title, const char* body)
2294	{
2295	    size_t n = (title ? strlen(title) : 0) + (body ? strlen(body) : 0);
2296	    uint32_t ms = 5000 + (uint32_t)(n * 60);
2297	    if (ms < LVGL_UI_NOTICE_MS) ms = LVGL_UI_NOTICE_MS;
2298	    if (ms > 30000) ms = 30000;
2299	    return ms;
2300	}
