2303	static void notice_show_locked(const char* title, const char* body,
2304	                               lv_color_t bar_color)
2305	{
2306	    if (!s_state.notice_screen) {
2307	        return;
2308	    }
2309	
2310	    /* The dim clock must never swallow a notice: wake the page (a key has to
2311	     * reach the notice, not just the wake gate) and remember to hand the screen
2312	     * back to the clock once the notice closes.  Hide it synchronously — the
2313	     * queued async hide would run after our screen load and yank the notice. */

2313	     * queued async hide would run after our screen load and yank the notice. */
2314	#ifdef CONFIG_AI_AGENT_STANDBY_UI
2315	    if (!s_state.notice_visible) {
2316	        s_state.notice_was_standby = standby_view_is_visible();
2317	        if (s_state.notice_was_standby) standby_view_hide_now();
2318	    }
2319	#endif
2320	
2321	    ui_activity_reset();   /* a notice is user-relevant activity */
2322	
2323	    if (s_state.notice_title) lv_label_set_text(s_state.notice_title, title ? title : "");
2324	    if (s_state.notice_body)  lv_label_set_text(s_state.notice_body, body ? body : "");
2325	    if (s_state.notice_bar)   lv_obj_set_style_border_color(s_state.notice_bar, bar_color, 0);
2326	
2327	    if (!s_state.notice_visible) {
2328	        s_state.notice_prev_screen = lv_screen_active();
2329	        lv_screen_load_anim(s_state.notice_screen, LV_SCR_LOAD_ANIM_FADE_IN,
2330	                            SCREEN_FADE_MS, 0, false);
2331	        s_state.notice_visible = true;
2332	    }
2333	
2334	    /* Later notice replaces the current one and restarts the window. */
2335	    notice_timer_cancel();
2336	    s_state.notice_timer = lv_timer_create(notice_timeout_cb,
2337	                                           notice_duration_ms(title, body), NULL);
2338	    if (s_state.notice_timer) {
2339	        lv_timer_set_repeat_count(s_state.notice_timer, 1);
2340	        lv_timer_set_auto_delete(s_state.notice_timer, true);
2341	    }
2342	
2343	    syslog(LOG_INFO, "[%s] show: %s | %s\n", NOTICE_TAG,
2344	           title ? title : "", body ? body : "");
2345	}
